select rating_bucket, country_list, stddev_rating from (select case when rating >= 4.3 then 'high' when rating >= 2.0 then 'mid' else 'low' end as rating_bucket, sort_array(collect_set(country)) as country_list, round(stddev(rating), 2) as stddev_rating from suppliers where length(supplier_name) > 8 group by case when rating >= 4.3 then 'high' when rating >= 2.0 then 'mid' else 'low' end) as t where stddev_rating < 65
